function allocation(s){const rows=[...s.rows].sort((a,b)=>(b.value||0)-(a.value||0)),total=rows.reduce((a,h)=>a+Math.max(0,h.value||0),0);let offset=0;const segments=rows.map((h,i)=>{const share=total?Math.max(0,h.value||0)/total*100:0,segment=`<circle cx="60" cy="60" r="48" pathLength="100" fill="none" stroke="${COLORS[i%COLORS.length]}" stroke-width="6" stroke-dasharray="${Math.max(0,share-.35)} ${100-Math.max(0,share-.35)}" stroke-dashoffset="${-offset}" transform="rotate(-90 60 60)"><title>${esc(assetName(h))}: ${share.toFixed(1)}%</title></circle>`;offset+=share;return segment;}).join('');const legend=(h,i)=>`<div class="allocation-row"><i class="dot" style="background:${COLORS[i%COLORS.length]}"></i><span class="allocation-name">${esc(assetName(h))}<small class="small-date">${esc(h.symbol)}</small></span><strong>${total?((h.value||0)/total*100).toFixed(1):'0'}%</strong></div>`;return `<div class="panel allocation-panel"><div class="panel-head"><h2>Allocation</h2><span class="pill">${rows.length} positions</span></div><div class="allocation-donut"><svg viewBox="0 0 120 120" role="img" aria-label="Allocation by investment value"><circle cx="60" cy="60" r="48" fill="none" stroke="var(--chart-grid)" stroke-width="6"/>${segments}</svg><div class="donut-total"><small>Investments value</small><strong>${money(s.value)}</strong><span>${esc(state.base)}</span></div></div>${rows.slice(0,5).map(legend).join('')||'<p class="empty">Connect an account to see your allocation.</p>'}${rows.length>5?`<details class="allocation-details"><summary>Show ${rows.length-5} more positions</summary>${rows.slice(5).map((h,i)=>legend(h,i+5)).join('')}</details>`:''}<p class="annual-note">${s.missing.length?'Partial allocation · some prices or FX unavailable.':'By current investment value · '+esc(state.base)}</p>${benchmarkReference({intraday:true,label:'Latest session · price reference'})}</div>`;}
function returnBreakdown(){const c=performanceContext(),capital=investedCapital(c.tx,state.base,fx,c.holdings,c.broker),p=portfolioPerformance(c.tx,quotes,state.base,fx,c.holdings,c.broker),amount=k=>p.complete?money(p[k]):'—';return `<div class="panel return-panel"><div class="panel-head"><h2>Return breakdown</h2><span class="pill">Total</span></div><div class="capital-summary"><small>Invested capital · current holdings at cost</small><strong>${money(capital.currentCost)}</strong></div><div class="return-line"><span>${c.broker?'XTB/manual purchases recorded':'Total purchases recorded'}</span><strong>${money(capital.purchases)}</strong></div><div class="return-line"><span>Unrealised gains</span><strong class="${p.unrealized>=0?'positive':'negative'}">${amount('unrealized')}</strong></div><div class="return-line"><span>Realised gains</span><strong class="${p.realized>=0?'positive':'negative'}">${amount('realized')}</strong></div><div class="return-line"><span>Dividends received</span><strong>${amount('paid')}</strong></div><div class="return-line return-total"><span>Total return</span><strong class="${p.gain>=0?'positive':'negative'}">${amount('gain')}</strong></div><p class="annual-note">Purchases recorded sum all recorded buys including fees; they can include reinvested sale proceeds and are not cash deposits. ${c.broker?'Trading 212 lifetime purchases require its trade history. ':''}Includes recorded dividends after reported tax and fees. ${c.broker&&!p.brokerReported?'Sync Trading 212 for its all-time realised gains. ':''}Reference FX conversions apply.</p></div>`;}
