 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!confirm('Delete this transaction?'))return;try{const next=state.transactions.filter(t=>t.id!==b.dataset.delete);ledger(next);state.transactions=next;save();render();}catch(e){toast(e.message);}});
