async function clear(){if(!confirm('Clear this portfolio from this browser? Export a backup first if needed.'))return;secureSession.clear();brokerSession=null;try{await forgetSavedConnection();}catch(e){notice('Could not forget the saved connection: '+e.message);return;}state.transactions=[];delete state.t212History;state.xtbAccounts=[];state.performance=[];state.assetNames={};state.demo=false;accountFilter='all';delete state.broker;brokerError='';quotes={};save();render();}
