let t212Draft=null,t212ReadVersion=0;
function validateHistoryArchive(h){if(!h||!['live','demo'].includes(h.environment)||typeof h.accountId!=='string'||!/^\d{1,64}$/.test(h.accountId)||(!Array.isArray(h.transactions)&&!Array.isArray(h.records)))throw Error('Invalid Trading 212 history account.');const transactions=mergeT212History([],historyRecords(h)).transactions,mappings={};const keys=new Set(transactions.map(t=>t.instrumentKey));for(const [k,v] of Object.entries(h.mappings||{})){if(!keys.has(k)||typeof v!=='string'||!(/^[A-Z0-9^][A-Z0-9.^=\-]{0,24}$/.test(v)))throw Error('Invalid history market-symbol mapping.');mappings[k]=v;}const result={version:1,environment:h.environment,accountId:h.accountId,transactions,mappings};ledger(mappedT212History(result));return packHistory(result);}
function openT212History(){t212ReadVersion++;t212Draft=state.t212History?{transactions:historyRecords(state.t212History),added:0,duplicates:0,issues:[],ignored:{},mappings:{...state.t212History.mappings}}:null;$('#t212-history-account').value=state.broker?.accountId||state.t212History?.accountId||'';$('#t212-history-environment').value=state.broker?.environment||state.t212History?.environment||'live';$('#t212-history-files').value='';$('#t212-history-error').textContent='';renderT212Preview();$('#t212-history-dialog').showModal();}
function renderT212Preview(){const out=$('#t212-history-output');$('#t212-history-save').disabled=!t212Draft||!!t212Draft.issues.length;if(!t212Draft){out.innerHTML='<p>Select your CSV exports to preview the combined ledger.</p>';return;}const instruments=historyInstruments(t212Draft.transactions),missing=instruments.filter(i=>!(t212Draft.mappings[i.key]||suggestedHistoryMapping(i,state.broker))),dates=t212Draft.transactions.map(t=>t.date).sort();out.innerHTML=`<div class="read-only-note"><strong>${t212Draft.added} new records · ${t212Draft.duplicates} duplicates skipped</strong><p>${t212Draft.transactions.length} investment records · ${esc(dates[0]||'')}–${esc(dates.at(-1)||'')} · ${instruments.length} instruments</p><p>${missing.length} instruments need a market-symbol mapping. You can save the ledger now; their missing prices will remain explicit chart gaps.</p><p>Current holdings and API dividends are kept unchanged. CSV dividends and tax corrections are used only in the reconstructed history. Native acquisition costs are translated using reference FX; cash balances and exact broker FX profit are not reconstructed.</p></div>${t212Draft.issues.length?`<div class="broker-error"><strong>Resolve ${t212Draft.issues.length} issues</strong>${t212Draft.issues.slice(0,30).map(i=>`<p>${esc(i)}</p>`).join('')}</div>`:''}<details class="annual-note"><summary>Excluded cash activity</summary>${Object.entries(t212Draft.ignored).map(([k,v])=>`<p>${esc(k)}: ${v}</p>`).join('')||'<p>No additional cash activity in this selection.</p>'}</details><details><summary>Review history market symbols (${missing.length} need mapping)</summary><p class="annual-note">Use the exchange listing in the stated currency. Leave uncertain listings blank. GBX prices have been converted to GBP. Suggested US listings and existing broker mappings are prefilled.</p>${[...missing,...instruments.filter(i=>!missing.includes(i))].map(i=>`<label class="mapping-row"><span><strong>${esc(i.name)}</strong><small class="small-date">${esc(i.ticker)} · ${esc(i.currency)} · ${esc(i.isin)}</small></span><input data-history-map="${esc(i.key)}" value="${esc(t212Draft.mappings[i.key]||suggestedHistoryMapping(i,state.broker))}" maxlength="25" aria-label="History market symbol for ${esc(i.name)}" placeholder="e.g. VWCE.DE"></label>`).join('')}</details>`;}
$('#t212-history-close').onclick=()=>{$('#t212-history-dialog').close();t212ReadVersion++;};
$('#t212-history-dialog').addEventListener('cancel',()=>{t212ReadVersion++;});
$('#t212-history-files').onchange=async e=>{const files=[...e.target.files],version=++t212ReadVersion;$('#t212-history-error').textContent='';$('#t212-history-save').disabled=true;if(!files.length)return;try{if(files.length>20||files.reduce((n,f)=>n+f.size,0)>10_000_000)throw Error('Select up to 20 CSV files, 10 MB combined.');$('#t212-history-output').textContent='Reading CSV exports locally…';const results=[];for(const file of files){if(!/\.csv$/i.test(file.name))throw Error('Select CSV exports only.');results.push(await parseT212History(await file.text()));if(version!==t212ReadVersion)return;}const issues=results.flatMap(r=>r.issues),ignored={};for(const r of results)for(const [k,v] of Object.entries(r.ignored))ignored[k]=(ignored[k]||0)+v;let merged;try{merged=mergeT212History(state.t212History?historyRecords(state.t212History):[],results.flatMap(r=>r.transactions));}catch(err){issues.push(err.message);merged={transactions:results.flatMap(r=>r.transactions),added:0,duplicates:0};}t212Draft={...merged,issues,ignored,mappings:{...state.t212History?.mappings}};renderT212Preview();}catch(err){if(version===t212ReadVersion){t212Draft=null;$('#t212-history-output').textContent='';$('#t212-history-error').textContent=err.message;}}};
$('#t212-history-save').onclick=()=>{try{if(!t212Draft||t212Draft.issues.length)throw Error('Resolve statement issues before importing.');const accountId=$('#t212-history-account').value.trim(),environment=$('#t212-history-environment').value;if(state.broker&&(accountId!==state.broker.accountId||environment!==state.broker.environment))throw Error('Select the connected Trading 212 account and environment. Other accounts cannot be merged into it.');if(state.t212History&&(accountId!==state.t212History.accountId||environment!==state.t212History.environment))throw Error('This browser already has history for another Trading 212 account. Keep its backup and use a separate browser profile.');const mappings={...t212Draft.mappings};document.querySelectorAll('[data-history-map]').forEach(input=>{const value=input.value.trim().toUpperCase();if(value)mappings[input.dataset.historyMap]=value;else delete mappings[input.dataset.historyMap];});const history=validateHistoryArchive({accountId,environment,transactions:t212Draft.transactions,mappings});if(!confirm(`Save ${historyRecords(history).length} Trading 212 history records for ${environment} account ${accountId}? ${t212Draft.added} new; ${t212Draft.duplicates} duplicates skipped. Current holdings, dividend cards and saved connections are kept.`))return;const next={...state,t212History:history,transactions:state.demo?[]:state.transactions,demo:false};try{localStorage.setItem(KEY,JSON.stringify(next));}catch{throw Error('Browser storage is full or unavailable. Nothing was imported. Export a backup before retrying.');}state=next;$('#t212-history-dialog').close();accountFilter='all';performanceRange=365;historyChartCache=null;render();loadPerformanceHistory().catch(e=>notice(e.message));loadBenchmark(true);toast('Trading 212 history saved. Current holdings were kept.');}catch(err){$('#t212-history-error').textContent=err.message;}};

function investmentGrowthPanel(c,p,tx,history,replayed){
 let points=investmentGrowth(history);const first=points[0];
 if(state.chartCurrencyInfluence&&first&&replayed){const fixed=historyWindow(fixedHistoricalChart(tx,first.date),performanceRange).filter(p=>p.date>=first.date);points=growthCurrency(points,fixed);}
 points=monetaryGrowth(growthBenchmark(points,dailyBenchmark(points.map(p=>p.date),benchmarkData.daily,benchmarkData.fxRows,state.base)));const last=points.at(-1),loading=replayed&&historyData.loading&&!historyData.hasLoaded,hasData=points.length>1&&!loading;
 const controls=`<div class="performance-controls"><select id="chart-metric" aria-label="Chart metric">${Object.entries(PERFORMANCE_METRICS).map(([key,label])=>`<option value="${key}" ${chartMetric===key?'selected':''}>${esc(label)}</option>`).join('')}</select>${performancePeriods()}${capitalControl()}${partialHistoryControl()}${chartCurrencyControl()}</div>`;
 let chart=`<div class="performance-empty">${loading?'Rebuilding adjusted investment value…':'Not enough consecutive complete valuations to calculate investment gains. Missing history is not treated as zero.'}</div>`;
 if(hasData){const keys=['chartValue','benchmarkValue',...(state.chartCurrencyInfluence?['priceOnlyValue']:[])],scale=chartScale(points.flatMap(p=>keys.map(k=>p[k]))),start=Date.parse(first.date),span=Date.parse(last.date)-start,x=p=>24+(Date.parse(p.date)-start)/span*652;
 chart=`<div class="benchmark-legend"><span><i class="portfolio-key"></i>Adjusted value · ${money(last.chartValue)}</span><span><i class="benchmark-key"></i>S&P 500 starting-capital reference · ${money(last.benchmarkValue)}</span>${state.chartCurrencyInfluence?`<span><i class="price-only-key"></i>At starting FX · ${money(last.priceOnlyValue)}</span><span><i class="currency-key"></i>FX influence · ${money(last.currencyAmount)}</span>`:''}</div><div class="scaled-chart historical-main-chart">${valueAxis(scale.ticks,scale.y)}<svg class="chart" viewBox="0 0 700 215" preserveAspectRatio="none" role="img" aria-label="Portfolio value excluding added capital in ${esc(state.base)}"><title>Portfolio value excluding added capital · ${esc(state.base)}</title>${scale.ticks.map(v=>`<line x1="0" x2="700" y1="${scale.y(v)}" y2="${scale.y(v)}" stroke-dasharray="4 6"/>`).join('')}${keys.map(k=>seriesSegments(points,k).map(segment=>`<polyline data-series="${k==='chartValue'?'investment-growth':k}" class="${k==='benchmarkValue'?'benchmark-line':k==='priceOnlyValue'?'price-only-line':''}" points="${segment.map(p=>x(p)+','+scale.y(p[k])).join(' ')}" fill="none" stroke="var(--chart-line)" stroke-width="2" vector-effect="non-scaling-stroke"/>`).join('')).join('')}${points.map(p=>`<circle cx="${x(p)}" cy="${scale.y(p.chartValue)}" r="4" fill="transparent"><title>${esc(p.date)} · ${esc(money(p.chartValue))} · Investment gain ${esc(money(p.periodGain))}</title></circle>`).join('')}</svg></div><div class="chart-labels"><span>${date(first.date)}</span><span>Added capital excluded · ${esc(state.base)}</span><span>${date(last.date)}</span></div>`;}
 const t212=tx.some(t=>t.source==='t212-history');return `<div class="panel portfolio-chart"><div class="panel-head"><div><h2>Portfolio value</h2><p class="muted">${esc(accountLabel(accountFilter))} · added capital excluded · ${esc(state.base)}</p></div>${controls}</div><div class="asset-price">${hasData?money(last.chartValue):'—'} <span class="pill">Adjusted value</span></div>${hasData?`<p class="muted">Investment gain over this window: <strong class="${last.periodGain>=0?'positive':'negative'}">${money(last.periodGain)}</strong> · opening value ${money(first.value)}.</p>`:''}<div class="chart-coverage-note"><strong>${replayed?'Recorded trade ledgers':'Saved daily observations'}</strong><span>${replayed?(t212?'Trading 212 CSV history and other imported ledgers are included where available.':c.broker?'Trading 212 snapshots are excluded; import its CSV history to include earlier trades.':'Imported/manual investment history.'):'Based on saved account observations; missing days may shorten the usable window.'} Current portfolio value: ${p.complete?money(p.value):'unavailable'}. Cash balances are excluded.</span></div>${replayed?historicalCoveragePanel(history,{returns:true}):''}${chart}<p class="annual-note">The line shows opening investment value plus cumulative investment profit in ${esc(state.base)}. Added or withdrawn capital does not count as a gain or loss. Recorded ledgers use actual trade cash flows and income; saved observations use changes in reported profit. Includes recorded dividends, fees and currency movements. Only the latest uninterrupted window with complete valuations is shown. ${state.chartCurrencyInfluence?'The blue line shows the same gains at starting FX; the currency influence is the monetary difference. ':''}S&P 500 is a price-index reference rebased to the opening capital, without later contributions or index dividends; it is not a cash-flow-matched benchmark. This is a reconstructed value, not a cash balance or tax figure.</p>${replayed&&(historyData.errors.length||!hasData)?`<details class="annual-note"><summary>Historical data coverage</summary>${historyData.errors.map(e=>`<p>${esc(e)}</p>`).join('')||'<p>Complete prices and FX are required for at least two consecutive valuations.</p>'}</details>`:''}</div>`;
}

function resolvedHistoryListings(){const tx=historicalTransactions(state,accountFilter),rows=[...new Map(tx.filter(t=>historyData.series[t.symbol]?.resolvedSymbol).map(t=>[t.symbol,{name:t.name||t.brokerSymbol,...historyData.series[t.symbol]}])).values()];return rows.length?`<details><summary>Automatically matched historical listings (${rows.length})</summary><p>Matches use the statement’s ISIN. Alternate listings can have different closing times. Converted prices use dated reference FX, not today’s rate. Use Review Trading 212 history mappings to override a match.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Holding</th><th>Market-data listing</th><th>Price currency</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.resolvedSymbol)}</td><td>${esc(r.resolvedCurrency||r.currency)}${r.resolvedCurrency?' → '+esc(r.currency)+' · dated FX':''}</td></tr>`).join('')}</tbody></table></div></details>`:'';}
function historicalCoveragePanel(points,{returns=false}={}){if(historyData.loading&&!historyData.hasLoaded)return '<div class="historical-coverage" data-history-coverage><strong>Loading historical price coverage…</strong><p>Checking dated prices and FX before counting missing holdings.</p></div>';const report=coverageReport(points);if(!points.some(p=>p.totalHoldings!==undefined))return '';const latest=points.at(-1),lastPlotted=[...points].reverse().find(p=>Number.isFinite(p.chartValue??p.value));return `<div class="historical-coverage" data-history-coverage><strong>Historical price coverage</strong><p>Unmapped Trading 212 instruments are looked up by exact ISIN and quote currency automatically. An alternate exchange listing of the same share class may be used, converted with dated daily FX when needed. These are reference valuations, not necessarily the original venue close; unknown history stays explicit.</p><p>${report.completeDays} complete days · ${report.partialDays} partial days · ${report.unavailableDays} days with no priced holdings${latest?' · '+esc(latest.date)+': '+latest.coveredHoldings+'/'+latest.totalHoldings+' holdings priced':''}.</p>${returns?'<p>Growth and benchmark comparisons require complete valuations. Partial subtotals are not used to calculate returns.</p>':`<div class="benchmark-legend"><span><i class="portfolio-key"></i>Complete holding values</span><span><i class="partial-history-key"></i>Known holdings subtotal · partial</span></div><p>${state.showPartialHistory===false?'Partial subtotals are hidden. Enable Show partial history to display the available holdings.':'Dashed amber segments show only holdings with usable prices and FX, not the full portfolio. Segments break when the missing holdings change; a coverage change is not a market move.'} ${lastPlotted?'Latest plotted valuation: '+esc(lastPlotted.date)+'.':''} Coverage counts holdings, not a percentage of portfolio value.</p>`}${resolvedHistoryListings()}${report.missing.length?`<details><summary>Missing holdings and dates (${report.missing.length})</summary><p>These omissions explain partial totals and gaps. Prices are not estimated from purchase cost or today’s holdings.</p>${state.t212History?'<button type="button" class="secondary" data-history-mappings>Review Trading 212 history mappings</button>':''}<div class="table-wrap"><table class="data-table"><thead><tr><th>Holding</th><th>Account</th><th>First / last missing date</th><th>Days</th><th>Reason</th></tr></thead><tbody>${report.missing.map(h=>`<tr><td>${esc(h.name)}<small class="small-date">${esc(historySymbolLabel(h.symbol))} · ${esc(h.currency)}</small></td><td>${esc(accountLabel(h.accountId))}</td><td>${esc(h.from)}–${esc(h.to)}</td><td>${h.days}</td><td>${h.reasons.map(esc).join('; ')}</td></tr>`).join('')}</tbody></table></div></details>`:''}</div>`;}
